"use strict";(self.webpackChunkwhimsylabs_website=self.webpackChunkwhimsylabs_website||[]).push([[2763],{2763(e,s,n){n.d(s,{content:()=>u,description:()=>o,keywords:()=>a,title:()=>r});n(5043);var t=n(7295),i=n(579);const r="Nous exposons au Bett 2026 : Rejoignez-nous \xe0 Londres",o="WhimsyLabs revient au Bett UK 2026 dans la Startup Zone pour pr\xe9senter notre laboratoire virtuel prim\xe9. Rendez-vous au stand FS10.",a=["Bett 2026","Bett UK exposition","salon EdTech Londres","d\xe9mo laboratoire virtuel","startup technologie \xe9ducative","WhimsyLabs Bett","ExCel Londres EdTech","innovation \xe9ducation STEM","plateforme laboratoire virtuel","technologie \xe9ducation scientifique"],u=(0,i.jsxs)("div",{children:[(0,i.jsx)("p",{children:"Je suis ravie d'annoncer que WhimsyLabs retourne au Bett UK en janvier 2026 ! Apr\xe8s notre exp\xe9rience incroyable au Bett 2025 o\xf9 nous avons re\xe7u une reconnaissance du Kids Judge Bett Award, nous revenons \xe0 l'ExCel London pour pr\xe9senter ce que nous avons construit ! Cette fois, nous serons dans la Startup Zone au stand FS10 dans le South Stand, et j'ai vraiment h\xe2te de rencontrer des \xe9ducateurs, des \xe9tudiants et d'autres innovateurs qui partagent notre passion pour la transformation de l'enseignement des STEM."}),(0,i.jsx)("h2",{children:"Pourquoi le Bett 2026 est important pour nous"}),(0,i.jsx)("p",{children:"Bett est l'\xe9picentre mondial de l'innovation EdTech, r\xe9unissant plus de 30 000 \xe9ducateurs et 800 exposants de plus de 130 pays. Pour une petite \xe9quipe comme la n\xf4tre bas\xe9e \xe0 \xc9dimbourg, Bett repr\xe9sente une opportunit\xe9 extraordinaire de se connecter avec des \xe9ducateurs qui recherchent activement des solutions aux d\xe9fis auxquels nous nous sommes consacr\xe9s."}),(0,i.jsx)("p",{children:"Le Bett de l'ann\xe9e derni\xe8re a \xe9t\xe9 transformateur pour WhimsyLabs. Nous avons rencontr\xe9 des enseignants qui luttaient avec l'acc\xe8s aux laboratoires post-pand\xe9mie, des chefs d'\xe9tablissement essayant d'\xe9quilibrer les engagements de durabilit\xe9 avec l'enseignement pratique des sciences, et des \xe9tudiants qui s'illuminaient lorsqu'ils r\xe9alisaient qu'ils pouvaient effectuer de vraies exp\xe9riences dans notre environnement virtuel. Ces conversations ont valid\xe9 tout ce sur quoi nous avons travaill\xe9 et nous ont inspir\xe9s \xe0 pousser notre plateforme encore plus loin."}),(0,i.jsx)("img",{src:"/images/bett map.jpg",alt:"Plan vers le stand WhimsyLabs \xe0 l'exposition Bett",className:"rounded shadow center limited-size",style:{width:"0px",height:"0px",margin:"0",padding:"0",border:"none",position:"absolute",visibility:"hidden"}}),(0,i.jsx)("div",{style:{margin:"2rem 0"},children:(0,i.jsx)(t.A,{imagePath:"/images/bett map.jpg",pathData:"M 404 96 L 404 185 L 360 185 L 360 646 L 418 646 L 419 679 L 397 681",viewBox:"0 0 938 785",speed:3e-4,numTokens:3})}),(0,i.jsx)("p",{className:"caption",children:"Suivez le chemin anim\xe9 pour trouver notre stand FS10 dans la Startup Zone du South Stand \u2013 nous aurons des d\xe9monstrations en direct et des exp\xe9riences pratiques pr\xeates pour vous."}),(0,i.jsx)("h2",{children:"Ce que nous pr\xe9sentons cette ann\xe9e"}),(0,i.jsx)("p",{children:"Depuis Bett 2025, nous avons sans rel\xe2che am\xe9lior\xe9 notre plateforme en fonction des retours des \xe9ducateurs et des \xe9tudiants avec qui nous travaillons. Au Bett 2026, vous pourrez d\xe9couvrir de premi\xe8re main ce qui distingue WhimsyLabs des simulations de laboratoire virtuelles traditionnelles. Comme l'ann\xe9e derni\xe8re, nous avons pr\xe9par\xe9 un environnement bac \xe0 sable complet o\xf9 de v\xe9ritables d\xe9couvertes se produisent, mais cette fois, nous pr\xe9senterons toute une gamme d'exp\xe9riences diff\xe9rentes en chimie, biologie et physique !"}),(0,i.jsx)("p",{children:"Notre approche \xab La physicalit\xe9 d'abord \xbb signifie que lorsque vous interagissez avec notre laboratoire virtuel, vous d\xe9veloppez la m\xeame m\xe9moire musculaire et la m\xeame aisance proc\xe9durale que vous gagneriez dans un laboratoire physique. La recherche d\xe9montre syst\xe9matiquement que l'apprentissage incarn\xe9 \u2013 o\xf9 les actions physiques sont int\xe9gr\xe9es aux processus cognitifs \u2013 am\xe9liore consid\xe9rablement la r\xe9tention et la compr\xe9hension dans l'enseignement des sciences. \xc0 notre stand, vous comprendrez imm\xe9diatement ce que cela signifie en pratique."}),(0,i.jsx)("p",{children:"Nous d\xe9montrerons \xe9galement notre compatibilit\xe9 multiplateforme. Que vous utilisiez des casques VR, des ordinateurs portables ou des Chromebooks, WhimsyLabs offre une exp\xe9rience fluide optimis\xe9e pour votre mat\xe9riel. Cette flexibilit\xe9 est cruciale pour les \xe9coles avec des \xe9cosyst\xe8mes technologiques diversifi\xe9s, garantissant que tous les \xe9tudiants peuvent acc\xe9der \xe0 des exp\xe9riences de laboratoire de haute qualit\xe9, quels que soient les appareils disponibles. Venez essayer la version bureau/Chromebooks du logiciel et voir comment elle transforme l'exp\xe9rience d'apprentissage de vos \xe9tudiants, sans compromis sur l'interactivit\xe9 ou l'immersion."}),(0,i.jsx)("h2",{children:"Innovations que nous sommes ravis de d\xe9montrer"}),(0,i.jsx)("p",{children:"Nous pr\xe9senterons plusieurs fonctionnalit\xe9s dont je suis particuli\xe8rement fi\xe8re, notamment nos capacit\xe9s d'\xe9valuation am\xe9lior\xe9es. L'un des plus grands d\xe9fis auxquels les \xe9ducateurs sont confront\xe9s est d'\xe9valuer les comp\xe9tences pratiques de laboratoire d'une mani\xe8re \xe0 la fois authentique et \xe9volutive. Les rapports de laboratoire traditionnels ne parviennent souvent pas \xe0 capturer la comp\xe9tence r\xe9elle d'un \xe9tudiant dans les techniques de laboratoire."}),(0,i.jsx)("p",{children:"En plus de ce probl\xe8me, les examens scientifiques et les travaux de cours ont \xe9t\xe9 de plus en plus affect\xe9s par des outils d'IA qui peuvent g\xe9n\xe9rer des rapports textuels avec un minimum d'effort de la part des \xe9tudiants. Pour r\xe9soudre ce probl\xe8me, notre plateforme permet aux \xe9tudiants d'utiliser leurs propres donn\xe9es exp\xe9rimentales uniques qu'ils collectent \xe0 partir de leurs propres actions, permettant des questions d'\xe9valuation personnalis\xe9es li\xe9es \xe0 leurs r\xe9sultats individuels. Cela signifie qu'aucun deux \xe9tudiants n'obtiennent des questions identiques, \xe9liminant les pr\xe9occupations de plagiat et le probl\xe8me des \xe9tudiants utilisant ChatGPT pour g\xe9n\xe9rer leurs rapports de laboratoire qui affligent les rapports de laboratoire traditionnels tout en fournissant une \xe9valuation plus authentique de la compr\xe9hension. En nous \xe9loignant des \xab cl\xe9s de r\xe9ponse \xbb statiques trouv\xe9es sur des sites comme Chegg, nous for\xe7ons les \xe9tudiants \xe0 s'engager avec les donn\xe9es qu'ils ont r\xe9ellement g\xe9n\xe9r\xe9es et \xe0 justifier leurs propres \xe9tapes, d\xe9bruiter leurs propres donn\xe9es et tirer des conclusions sens\xe9es, rendant l'ensemble du processus plus authentique et plus difficile \xe0 \xab manipuler \xbb que les questions \xe0 choix multiples traditionnelles. Nous avons constat\xe9 que les \xe9tudiants qui \xab trichent \xbb effectuent effectivement les actions qu'un \xe9tudiant qui n'a pas trich\xe9 ferait ; en cherchant comment effectuer l'exp\xe9rience, r\xe9duire le bruit et analyser leurs propres donn\xe9es, ils finissent par apprendre le mat\xe9riel de toute fa\xe7on !"}),(0,i.jsx)("p",{children:"Notre syst\xe8me de notation automatis\xe9e a \xe9galement consid\xe9rablement \xe9volu\xe9. Les enseignants nous disent r\xe9guli\xe8rement que la correction des rapports de laboratoire est l'une de leurs responsabilit\xe9s les plus chronophages, certains y consacrant jusqu'\xe0 4-5 heures par semaine. Notre syst\xe8me \xe9value la technique de laboratoire et l'approche exp\xe9rimentale en temps r\xe9el, fournissant un retour imm\xe9diat aux \xe9tudiants tout en faisant \xe9conomiser aux \xe9ducateurs en moyenne 3,5 heures par semaine. C'est du temps que les enseignants peuvent r\xe9investir dans l'enseignement plut\xf4t que dans des t\xe2ches administratives."}),(0,i.jsxs)("p",{children:["Parce que notre simulation est construite sur un \xab bac \xe0 sable \xbb bas\xe9 sur la physique plut\xf4t qu'un script rigide, notre IA peut noter le"," ",(0,i.jsx)("i",{children:"processus"})," plut\xf4t que le r\xe9sultat final. Cela signifie que nous pouvons \xe9valuer des aspects nuanc\xe9s de la technique ; l'\xe9tudiant a-t-il st\xe9rilis\xe9 la boucle correctement ? Ont-ils titr\xe9 trop rapidement ? Les actions de l'\xe9tudiant, les comp\xe9tences de r\xe9solution de probl\xe8mes et l'approche unique sont mesur\xe9es. Et, comme tout scientifique vous le dira, les donn\xe9es sont bruit\xe9es. Notre syst\xe8me est con\xe7u pour avoir du bruit de fond et de l'al\xe9atoire, comme l'humidit\xe9 changeante, la temp\xe9rature, la contamination, les niveaux de lumi\xe8re et d'autres facteurs, le rendant plus r\xe9aliste et plus difficile \xe0 \xab manipuler \xbb que les questions \xe0 choix multiples traditionnelles."]}),(0,i.jsx)("p",{children:"Ce qui est peut-\xeatre le plus excitant, c'est notre constructeur d'exp\xe9riences personnalis\xe9es qui sera lanc\xe9 l'ann\xe9e prochaine, qui int\xe8gre maintenant l'assistance de l'IA pour l'alignement des programmes. Les \xe9ducateurs peuvent concevoir des sc\xe9narios de laboratoire sur mesure qui correspondent \xe0 leurs exigences curriculaires sp\xe9cifiques, qu'ils enseignent la chimie GCSE, la biologie IB ou la physique Advanced Placement. La flexibilit\xe9 ici est v\xe9ritablement sans pr\xe9c\xe9dent ; assurez-vous de passer pour voir notre d\xe9monstration vid\xe9o de cette nouvelle fonctionnalit\xe9 !"}),(0,i.jsx)("h2",{children:"Pourquoi la Startup Zone est confortable pour nous"}),(0,i.jsx)("p",{children:"Nous avons sp\xe9cifiquement choisi d'exposer dans la Startup Zone parce qu'elle repr\xe9sente ce que nous sommes : une \xe9quipe innovante et agile engag\xe9e \xe0 r\xe9soudre de vrais probl\xe8mes de mani\xe8re cr\xe9ative. C'est l\xe0 que les \xe9ducateurs viennent d\xe9couvrir l'avenir de la technologie \xe9ducative, pas seulement des am\xe9liorations incr\xe9mentales des solutions existantes. Cela nous offre \xe9galement de l'espace pour installer notre \xe9quipement VR et avoir des d\xe9monstrations plus interactives que nous ne pourrions le faire dans un stand plus grand et plus occup\xe9."}),(0,i.jsx)("p",{children:"\xcatre dans la Startup Zone signifie \xe9galement que nous pouvons avoir des conversations plus significatives et approfondies. Nous n'essayons pas de faire des milliers de ventes rapides, nous voulons comprendre vos d\xe9fis sp\xe9cifiques, d\xe9montrer comment WhimsyLabs les aborde et explorer si nous sommes le bon choix pour votre \xe9tablissement. L'atmosph\xe8re plus intime de la Startup Zone facilite exactement ce type de discussions substantielles. Cela nous permet de favoriser des connexions plus fortes avec les \xe9ducateurs qui sont aussi passionn\xe9s par l'am\xe9lioration de l'enseignement des STEM que nous le sommes, de sorte que lorsque nous lan\xe7ons notre plateforme publiquement, nos premiers utilisateurs sont ceux avec qui nous avons construit des relations et dont nous comprenons profond\xe9ment les besoins."}),(0,i.jsx)("h2",{children:"Accessibilit\xe9 et inclusivit\xe9 au c\u0153ur"}),(0,i.jsx)("p",{children:"Un aspect de WhimsyLabs dont je suis passionn\xe9e de discuter au Bett 2026 est notre engagement envers l'accessibilit\xe9. Nous avons int\xe9gr\xe9 la compatibilit\xe9 SEND et les aides \xe0 l'apprentissage multisensoriel directement dans notre plateforme d\xe8s le d\xe9but, et non comme des ajouts ult\xe9rieurs. La recherche montre que jusqu'\xe0 15% des \xe9tudiants de l'enseignement g\xe9n\xe9ral ont des besoins \xe9ducatifs sp\xe9ciaux, et les laboratoires traditionnels pr\xe9sentent souvent des obstacles importants pour ces apprenants."}),(0,i.jsx)("p",{children:"Notre environnement virtuel permet un rythme personnalisable, des entr\xe9es sensorielles ajustables et des modes d'interaction flexibles qui s'adaptent aux besoins individuels des \xe9tudiants. Les \xe9tudiants qui pourraient avoir du mal avec la surcharge sensorielle d'un laboratoire physique \u2013 comme les odeurs chimiques, le bruit, les pressions sociales ou les dangers potentiels \u2013 peuvent apprendre \xe0 leur propre rythme dans un environnement qu'ils contr\xf4lent. Il ne s'agit pas d'abaisser les normes ; il s'agit de supprimer les obstacles inutiles \xe0 l'apprentissage tout en maintenant la rigueur scientifique."}),(0,i.jsx)("h2",{children:"Durabilit\xe9 : Plus qu'un simple mot \xe0 la mode"}),(0,i.jsx)("p",{children:"Nous avons beaucoup \xe9crit sur les avantages environnementaux des laboratoires virtuels, et ce sera un point central de notre stand Bett 2026. Les laboratoires scientifiques traditionnels consomment d'\xe9normes ressources ; jusqu'\xe0 5 fois plus d'\xe9nergie et d'eau que les espaces de bureaux typiques \u2013 et g\xe9n\xe8rent des d\xe9chets plastiques substantiels gr\xe2ce aux consommables \xe0 usage unique."}),(0,i.jsx)("p",{children:"Alors que les \xe9coles du monde entier s'engagent vers des objectifs de neutralit\xe9 carbone, beaucoup se demandent comment maintenir un enseignement des STEM de qualit\xe9 tout en r\xe9duisant leur impact environnemental. WhimsyLabs offre une solution concr\xe8te : une exp\xe9rimentation illimit\xe9e avec z\xe9ro d\xe9chet physique, une r\xe9duction de 98% de la consommation d'\xe9nergie par rapport aux laboratoires traditionnels, et aucun co\xfbt continu pour les consommables ou l'\xe9limination des d\xe9chets dangereux. Au Bett, nous aurons des calculs d'impact d\xe9taill\xe9s disponibles pour que vous puissiez voir exactement comment WhimsyLabs pourrait contribuer aux objectifs de durabilit\xe9 de votre \xe9tablissement."}),(0,i.jsx)("h2",{children:"Ce que vous pouvez attendre au stand FS10"}),(0,i.jsx)("p",{children:"Lorsque vous visiterez notre stand, vous ne trouverez pas un discours de vente poli ou une d\xe9monstration soigneusement r\xe9p\xe9t\xe9e. Ce que vous trouverez, c'est moi et mon \xe9quipe, v\xe9ritablement enthousiastes de vous montrer ce que nous avons construit et de discuter honn\xeatement si cela correspond \xe0 vos besoins. Nous aurons les deux types d'appareils install\xe9s ; casques VR et un ordinateur portable, afin que vous puissiez d\xe9couvrir notre plateforme \xe0 travers diff\xe9rentes modalit\xe9s et voir comment elle fonctionne sur le mat\xe9riel que votre \xe9cole utilise. \xc9tant donn\xe9 que nous ne limitons pas l'acc\xe8s VR ou de bureau, vous pouvez d\xe9couvrir la plateforme de la mani\xe8re qui convient le mieux \xe0 vos besoins, exactement de la m\xeame mani\xe8re que vos \xe9tudiants le feront."}),(0,i.jsx)("p",{children:"Vous pourrez effectuer de v\xe9ritables exp\xe9riences, pas seulement regarder quelqu'un d'autre les faire. M\xe9langer des produits chimiques et observer des r\xe9actions r\xe9alistes. Configurer des exp\xe9riences de physique et manipuler des variables en temps r\xe9el. Diss\xe9quer des sp\xe9cimens virtuels avec la bonne technique. L'objectif est que vous compreniez visc\xe9ralement ce qui rend notre approche diff\xe9rente ; pourquoi nos \xe9tudiants rapportent que WhimsyLabs ressemble \xe0 un vrai laboratoire d'une mani\xe8re que d'autres plateformes virtuelles ne font pas, et pourquoi nous sommes ceux qui remportent les prix du choix des \xe9tudiants pour une plateforme amusante et \xe9ducative."}),(0,i.jsx)("p",{children:"Nous aurons \xe9galement des \xe9tudes de cas d'\xe9coles utilisant actuellement WhimsyLabs, y compris des donn\xe9es sur les r\xe9sultats d'apprentissage, les \xe9conomies de temps pour les enseignants et les mesures d'engagement des \xe9tudiants. Ce ne sont pas des histoires de r\xe9ussite tri\xe9es sur le volet \u2013 ce sont des \xe9valuations honn\xeates d'\xe9ducateurs qui ont int\xe9gr\xe9 notre plateforme dans leur enseignement et peuvent parler \xe0 la fois de ses forces et des domaines o\xf9 nous nous am\xe9liorons encore."}),(0,i.jsx)("h2",{children:"Pourquoi vous devriez nous rendre visite"}),(0,i.jsx)("p",{children:"Si vous avez du mal avec l'acc\xe8s aux laboratoires, que ce soit en raison de contraintes budg\xe9taires, de limitations d'installations ou de pr\xe9occupations de s\xe9curit\xe9, vous devriez nous rendre visite. Si vous cherchez des moyens de rendre l'enseignement des STEM plus inclusif et accessible aux apprenants diversifi\xe9s, vous devriez nous rendre visite. Si vous essayez d'\xe9quilibrer les engagements d'enseignement/administratifs avec l'enseignement pratique des sciences, vous devriez nous rendre visite."}),(0,i.jsx)("p",{children:"Mais m\xeame si aucun de ces d\xe9fis sp\xe9cifiques ne s'applique \xe0 vous, j'aimerais toujours vous rencontrer. Peut-\xeatre \xeates-vous simplement curieux de savoir o\xf9 va l'EdTech, ou vous voulez comprendre comment la r\xe9alit\xe9 virtuelle est appliqu\xe9e dans l'\xe9ducation au-del\xe0 du jeu et du divertissement. Peut-\xeatre \xeates-vous un \xe9tudiant ou un \xe9ducateur avec des id\xe9es sur ce que les laboratoires virtuels devraient faire qu'ils ne font pas actuellement. Chaque conversation est pr\xe9cieuse pour nous ; elles nous aident \xe0 comprendre o\xf9 concentrer nos efforts de d\xe9veloppement et \xe0 nous assurer que nous r\xe9solvons de vrais probl\xe8mes, pas des probl\xe8mes imaginaires."}),(0,i.jsx)("h2",{children:"Au-del\xe0 du sol d'exposition"}),(0,i.jsx)("p",{children:"Bett concerne bien plus que ce qui se passe dans les halls d'exposition. Il s'agit des conversations pendant les pauses caf\xe9, des connexions \xe9tablies en attendant les d\xe9monstrations, des id\xe9es qui \xe9mergent lorsque des \xe9ducateurs de diff\xe9rents contextes partagent leurs exp\xe9riences. J'esp\xe8re avoir beaucoup de ces discussions informelles tout au long de l'\xe9v\xe9nement."}),(0,i.jsx)("p",{children:"Si vous souhaitez planifier un moment sp\xe9cifique pour nous rencontrer, ou si vous avez des questions particuli\xe8res pour lesquelles vous aimeriez que nous nous pr\xe9parions, veuillez nous contacter \xe0 l'avance. Nous sommes heureux de r\xe9server du temps pour des discussions plus approfondies sur la mise en \u0153uvre, l'int\xe9gration des programmes, les exigences techniques ou tout autre \xe9l\xe9ment important pour votre processus de d\xe9cision. Vous pouvez nous contacter \xe0 hello@whimsylabs.ai"}),(0,i.jsx)("p",{children:"J'esp\xe8re vous voir au stand FS10 du 21 au 23 janvier 2026. Apportez votre curiosit\xe9, vos questions et votre passion pour l'enseignement des STEM. Nous apporterons les n\xf4tres, ainsi qu'une technologie vraiment passionnante que je pense que vous allez adorer."})]})}}]);
